"""Export preview from CAD STL triangles, not a fabrication drawing."""
import re,json,math, pathlib
P=pathlib.Path(__file__).parent
parts={}
for name in ('carrier','adapter','pc','guides','cables'):
 s=(P/f'{name}.stl').read_text()
 pts=[list(map(float,i)) for i in re.findall(r'vertex\s+([-+\d.eE]+)\s+([-+\d.eE]+)\s+([-+\d.eE]+)',s)]
 parts[name]=[pts[i:i+3] for i in range(0,len(pts),3)]
html='''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>H-7 / n4 — Modulo pioniere</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#101820;color:#eef1f4}*{box-sizing:border-box}body{margin:0}header{padding:20px 24px;border-bottom:1px solid #34434c}h1{margin:0;font-size:clamp(22px,4vw,34px);letter-spacing:-1px}small{color:#a9bdcb}main{display:grid;grid-template-columns:240px 1fr;min-height:75vh}aside{padding:16px;background:#17242d;display:flex;flex-direction:column;gap:10px}button,label{background:#21343f;border:1px solid #405765;color:#ecf4fa;padding:12px;border-radius:8px;text-align:left;cursor:pointer;font:inherit}button.active{background:#1d5767;border-color:#6dc6df}button:hover{background:#304c5b}canvas{width:100%;height:100%;min-height:480px;touch-action:none;background:radial-gradient(ellipse at center,#2b3942,#101820)}.stage{position:relative;min-width:0}.badge{position:absolute;top:12px;left:16px;pointer-events:none;color:#f0b46d;font-size:12px;letter-spacing:1px;text-transform:uppercase}footer{border-top:1px solid #34434c;padding:18px 24px;line-height:1.5;color:#bed0dc}a{color:#8bd5e8}h3{margin:6px 0 0;font-size:15px}input{accent-color:#65cbe5}.legend{font-size:13px;color:#b8cdd9}@media(max-width:700px){main{display:flex;flex-direction:column-reverse}.stage{height:58vh}canvas{min-height:0}aside{display:grid;grid-template-columns:1fr 1fr}aside h3,aside small{grid-column:1/-1}}
</style><header><small>LA TORRE / H-7 R-8.1 / 26 NOV 2026</small><h1>n4 · Fujitsu ESPRIMO</h1><small>C120 Universal + U-Fujitsu P0.1 · dima massima 65 × 195 × 190 mm</small></header><main><aside>
<h3>Vista</h3><button data-mode="assembly" class="active">Modulo montato</button><button data-mode="exploded">Esploso</button><button data-mode="tower">Sette sedi H-7</button><button data-mode="rear">Retro e cavi</button><button data-mode="front">Frontale</button><h3>Strati</h3>
<label><input type="checkbox" data-part="carrier" checked> C120 / alluminio</label><label><input type="checkbox" data-part="adapter" checked> U-Fujitsu / selle</label><label><input type="checkbox" data-part="pc" checked> Dima ESPRIMO</label><label><input type="checkbox" data-part="guides" checked> Guide fisse</label><label><input type="checkbox" data-part="cables"> Riserva cavi</label><small>Trascina per ruotare · rotella per zoom · le porte sono schematiche.</small></aside><div class="stage"><canvas id="c"></canvas><div class="badge">Studio geometrico · non fabbricare</div></div></main><footer><b>120 × 284 × 280 mm</b> · interasse 190 mm · tasca cavi minima 82 mm · 3 mm gioco nominale per guida.<br><b>Gate termico aperto:</b> 200 mm sulle superfici ventilate. Prima prova con vicini vuoti, previa verifica della mappa delle griglie. Alloggiamento n4 all'estremità solo candidato. <a href="p02/index.html">Nuova P0.2 A/B</a> · <a href="README.md">Dossier tecnico</a> · <a href="n4.scad">CAD OpenSCAD</a> · <a href="dummy.stl">STL dima inerte</a></footer>
<script>
const parts=DATA, c=document.querySelector('#c'),ctx=c.getContext('2d');let mode='assembly',yaw=-0.76,pitch=.34,zoom=1,drag=null;const visible={carrier:true,adapter:true,pc:true,guides:true,cables:false};
const colors={carrier:[143,163,175],adapter:[196,152,92],pc:[37,44,50],guides:[83,105,119],cables:[64,176,214],base:[84,100,111]};
function box(x,y,z,w,d,h){const v=[[x,y,z],[x+w,y,z],[x+w,y+d,z],[x,y+d,z],[x,y,z+h],[x+w,y,z+h],[x+w,y+d,z+h],[x,y+d,z+h]];return [[0,3,2,1],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]].flatMap(f=>[[v[f[0]],v[f[1]],v[f[2]]],[v[f[0]],v[f[2]],v[f[3]]]])}
function draw(){let dpr=Math.min(devicePixelRatio,2), w=c.clientWidth,h=c.clientHeight;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let target=mode==='tower'?[570,0,95]:mode==='exploded'?[0,0,170]:[0,0,130],scale=Math.min(w/(mode==='tower'?1540:490),h/(mode==='tower'?740:mode==='exploded'?500:390))*zoom, cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);
function project(v){let x=v[0]-target[0],y=v[1]-target[1],z=v[2]-target[2],a=cy*x-sy*y,b=sy*x+cy*y;return [w/2+a*scale,h/2-(z*cp+b*sp)*scale,b*cp-z*sp]}
let faces=[];function add(tris,name,offset=[0,0,0]){for(let tri of tris){let p=tri.map(v=>project(v.map((n,i)=>n+offset[i])));let edge=p[1].map((v,i)=>v-p[0][i]),e2=p[2].map((v,i)=>v-p[0][i]);let normal=[edge[1]*e2[2]-edge[2]*e2[1],edge[2]*e2[0]-edge[0]*e2[2],edge[0]*e2[1]-edge[1]*e2[0]],len=Math.hypot(...normal)||1;let lit=.7+.3*Math.abs((normal[0]*.3-normal[1]*.5+normal[2]*.8)/len);let col=colors[name];if(name==='pc'){let m=tri[0].map((v,i)=>(v+tri[1][i]+tri[2][i])/3);if(m[1]<-135.11&&m[0]<-25)col=[165,32,37];else if(m[1]<-135.13||m[0]>32.5)col=[165,171,176]}faces.push({p,z:(p[0][2]+p[1][2]+p[2][2])/3,color:col.map(x=>Math.round(x*lit)),name})}}
for(let [k,t] of Object.entries(parts))if(visible[k])add(t,k,mode==='exploded'?[0,0,k==='pc'?105:k==='adapter'?40:0]:[0,0,0]);if(mode==='tower'){for(let i=1;i<7;i++)if(visible.guides)add(parts.guides,'guides',[i*190,0,0]);for(let y of [-155,135])add(box(-92.5,y,-20,1325,20,20),'base');for(let i=0;i<7;i++)add(box(i*190-10,-135,-20,20,270,20),'base')}
const rw=Math.max(1,Math.round(w)),rh=Math.max(1,Math.round(h)),buf=ctx.createImageData(rw,rh),zbuf=new Float32Array(rw*rh);zbuf.fill(Infinity);
for(let f of faces){if(f.name==='cables')continue;let [a,b,c0]=f.p,den=(b[1]-c0[1])*(a[0]-c0[0])+(c0[0]-b[0])*(a[1]-c0[1]);if(Math.abs(den)<1e-8)continue;
let xmin=Math.max(0,Math.floor(Math.min(a[0],b[0],c0[0]))),xmax=Math.min(rw-1,Math.ceil(Math.max(a[0],b[0],c0[0]))),ymin=Math.max(0,Math.floor(Math.min(a[1],b[1],c0[1]))),ymax=Math.min(rh-1,Math.ceil(Math.max(a[1],b[1],c0[1])));
for(let y=ymin;y<=ymax;y++)for(let x=xmin;x<=xmax;x++){let u=((b[1]-c0[1])*(x+.5-c0[0])+(c0[0]-b[0])*(y+.5-c0[1]))/den,v=((c0[1]-a[1])*(x+.5-c0[0])+(a[0]-c0[0])*(y+.5-c0[1]))/den,k=1-u-v;if(u<0||v<0||k<0)continue;let z=u*a[2]+v*b[2]+k*c0[2],i=y*rw+x;if(z>=zbuf[i])continue;zbuf[i]=z;let j=i*4;buf.data[j]=f.color[0];buf.data[j+1]=f.color[1];buf.data[j+2]=f.color[2];buf.data[j+3]=255}}
const scratch=document.createElement('canvas');scratch.width=rw;scratch.height=rh;scratch.getContext('2d').putImageData(buf,0,0);ctx.drawImage(scratch,0,0,w,h);
for(let f of faces.filter(x=>x.name==='cables').sort((a,b)=>b.z-a.z)){ctx.beginPath();f.p.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle='rgba(64,176,214,.15)';ctx.fill();}
if(visible.pc){let P=project([0,-137,221+(mode==='exploded'?105:0)]);ctx.fillStyle='#d1edf4';ctx.font='bold 15px system-ui';ctx.fillText('n4',P[0]+8,P[1]-8)}
}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));yaw=mode==='rear'?2.5:mode==='front'?0:mode==='tower'?-.15:-.76;pitch=mode==='front'?0:.34;zoom=1;if(mode==='rear'){visible.cables=true;document.querySelector('[data-part=cables]').checked=true}draw()});document.querySelectorAll('[data-part]').forEach(b=>b.onchange=()=>{visible[b.dataset.part]=b.checked;draw()});c.onpointerdown=e=>{drag=[e.clientX,e.clientY];c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.01;pitch=Math.max(-1.3,Math.min(1.3,pitch+(e.clientY-drag[1])*.01));drag=[e.clientX,e.clientY];draw()};c.onpointerup=c.onpointercancel=()=>drag=null;c.onwheel=e=>{e.preventDefault();zoom=Math.max(.45,Math.min(3,zoom*Math.exp(-e.deltaY*.001)));draw()};new ResizeObserver(draw).observe(c);draw();
</script></html>'''
(P/'index.html').write_text(html.replace('DATA',json.dumps(parts,separators=(',',':'))))
